  "findings": [
    {
      "tipo": "GC",
      "causa_raiz": "Alocação massiva e contínua de memória gerenciada no método Update() devido à concatenação de strings em laço de repetição ('s += i.ToString()') e alocações repetitivas de arrays de objetos ('new object[10000]'). Cada concatenação de string cria um novo objeto imutável na memória Heap, gerando mais de 6.7 MB de lixo por frame e disparando pausas síncronas do Garbage Collector de mais de 23 ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(gcConcatIterations * 4);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i));
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                // FindObjectsOfType em Update foi removido para evitar travamentos de CPU.
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    _propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, textos (strings) não podem ser alterados depois de criados. Quando você usa o operador '+' para juntar textos dentro de um laço no Update, a Unity cria uma nova string na memória RAM (Heap) centenas de vezes por segundo. Quando a memória enche, a Unity precisa congelar o jogo inteiro (Garbage Collection) para limpar essa bagunça, causando travamentos visíveis (stuttering). Ao reutilizar um StringBuilder ou evitar gerar lixo por frame, você mantém a memória limpa e a taxa de quadros estável."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva de 'GameObject.FindObjectsOfType<GameObject>()' dentro de um laço de repetição no método Update(). Este método varre toda a lista de objetos da cena na camada nativa de C++ da Unity e aloca um array gerenciado a cada iteração, gerando picos de CPU de até 118 ms (ultrapassando violentamente o orçamento de 16.7 ms para 60 FPS).",
      "codigo_refatorado": "using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    // Exemplo de padrão recomendado: Gerenciador de instâncias em cache
    public class SceneObjectRegistry : MonoBehaviour
    {
        private static readonly System.Collections.Generic.List<GameObject> RegisteredObjects = new System.Collections.Generic.List<GameObject>();

        public static void Register(GameObject go) => RegisteredObjects.Add(go);
        public static void Unregister(GameObject go) => RegisteredObjects.Remove(go);
        public static System.Collections.Generic.IReadOnlyList<GameObject> AllObjects => RegisteredObjects;
    }
}",
      "explicacao_didatica": "A função FindObjectsOfType funciona como um guarda procurando um arquivo específico revirando todas as gavetas de todos os prédios da cidade a cada fração de segundo. Em vez de pedir para o jogo buscar todos os objetos do zero a cada frame, faça com que os próprios objetos se registrem em uma lista quando forem criados (Awake/Start) e se retirem quando destruídos (OnDestroy). Assim, a lista já fica pronta para uso sem custo de processamento."
    }
  ],
  "dicas_level_design": null
}

